begin;
select plan(18);
select has_table('public','together_billing_subscriptions','Normalized provider subscriptions exist');
select has_column('public','together_billing_subscriptions','cancel_at_period_end','Cancellation-at-period-end is stored');
select has_column('public','together_billing_subscriptions','trial_end','Trial end is stored');
select has_column('public','together_billing_subscriptions','access_ends_at','Application access end is explicit');
select has_column('public','together_billing_events','attempts','Webhook attempts are tracked');
select has_column('public','together_credit_ledger','stripe_invoice_id','Stripe invoice references are auditable');
select has_column('public','together_credit_ledger','stripe_payment_intent_id','Stripe payment references are auditable');
select has_table('public','together_billing_adjustments','Refund and dispute adjustments are auditable');
select ok((select relrowsecurity from pg_class where oid='public.together_billing_subscriptions'::regclass),'Subscription rows use RLS');
select ok((select relrowsecurity from pg_class where oid='public.together_billing_adjustments'::regclass),'Adjustment rows use RLS');
select ok(not has_table_privilege('authenticated','public.together_billing_subscriptions','INSERT'),'Clients cannot create subscriptions');
select ok(not has_table_privilege('authenticated','public.together_billing_adjustments','INSERT'),'Clients cannot create billing adjustments');
select ok(to_regprocedure('public.kivelle_apply_credit_purchase_reversal(uuid,uuid,integer,text,text,text,jsonb)') is not null,'Atomic purchase reversal RPC exists');
select ok(not has_function_privilege('authenticated','public.kivelle_apply_credit_purchase_reversal(uuid,uuid,integer,text,text,text,jsonb)','EXECUTE'),'Clients cannot invoke purchase reversals');
select ok(to_regprocedure('public.kivelle_grant_subscription_credit_target(uuid,integer,integer,text,text,jsonb)') is not null,'Atomic monthly target grant RPC exists');
select ok(not has_function_privilege('authenticated','public.kivelle_grant_subscription_credit_target(uuid,integer,integer,text,text,jsonb)','EXECUTE'),'Clients cannot invoke monthly target grants');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_billing_subscriptions'::regclass and pg_get_constraintdef(oid) ilike '%provider_subscription_id%'),'Provider subscription identity is unique');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_billing_adjustments'::regclass and pg_get_constraintdef(oid) ilike '%provider_event_id%'),'Adjustment events are idempotent');
select * from finish();
rollback;
